// The campaign summary: ONE rolling "story so far" per room (`campaign_summary`, id
// `summary`), regenerated by folding the oldest chronicle records into it.
//
// `throughTurn` is the newest turn the summary has absorbed. It only moves forward, and it
// is what lets the engine stop replaying history: every message of a turn at or below it
// is covered by the summary (see `mayReplay` in `fold.ts`).
//
// `keeper` is the Keeper's margin — keeper-editable, never written by a fold (the fold
// input is player-grade text only), carried forward verbatim across regenerations.
// `foldMeter` is the meter reading the last routine fold acted on (the re-arm stamp).
//
// Who sees what:
//   - keeper: everything;
//   - admin, player, observer, an NPC actor: the text and its through-turn — the
//     spoiler-free "previously on…". Never the margin or the fold bookkeeping.
import type { Document, DocumentType, JsonObject, Viewer, WriteViolation } from "../documents/model.ts";
import type { FoldMeterStamp } from "./fold.ts";

export const CAMPAIGN_SUMMARY_TYPE = "campaign_summary";
export const CAMPAIGN_SUMMARY_ID = "summary";

/** The hard ceiling on summary text; a room's configured limit (`summaryMaxChars`) sits below it. */
export const MAX_SUMMARY_CHARS = 16_000;
export const MAX_KEEPER_MARGIN_CHARS = 4_000;

export interface CampaignSummary {
  readonly text: string;
  readonly throughTurn: number;
  readonly foldCount: number;
  readonly keeper: string;
  readonly foldMeter: FoldMeterStamp | null;
}

function codePoints(text: string): number {
  let count = 0;
  for (const _ of text) count++;
  return count;
}

function count(value: unknown): boolean {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

function isRecord(value: unknown): value is JsonObject {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

const SUMMARY_FIELDS: ReadonlySet<string> = new Set(["text", "throughTurn", "foldCount", "keeper", "foldMeter"]);

export function validateCampaignSummary(data: JsonObject): WriteViolation[] {
  const violations: WriteViolation[] = [];
  for (const key of Object.keys(data)) if (!SUMMARY_FIELDS.has(key)) violations.push({ code: "unknown_field", path: key });
  const text = data.text;
  if (typeof text !== "string") violations.push({ code: "bad_field", path: "text" });
  else if (text.trim() === "") violations.push({ code: "empty", path: "text" });
  else if (codePoints(text) > MAX_SUMMARY_CHARS) violations.push({ code: "too_long", path: "text" });
  if (!count(data.throughTurn)) violations.push({ code: "bad_field", path: "throughTurn" });
  if (!count(data.foldCount)) violations.push({ code: "bad_field", path: "foldCount" });
  if (typeof data.keeper !== "string") violations.push({ code: "bad_field", path: "keeper" });
  else if (codePoints(data.keeper) > MAX_KEEPER_MARGIN_CHARS) violations.push({ code: "too_long", path: "keeper" });
  const meter = data.foldMeter;
  if (meter !== null) {
    if (!isRecord(meter) || !count(meter.tokens) || typeof meter.estimated !== "boolean" || Object.keys(meter).length !== 2) {
      violations.push({ code: "bad_field", path: "foldMeter" });
    }
  }
  return violations;
}

export function campaignSummaryData(summary: CampaignSummary): JsonObject {
  return {
    text: summary.text,
    throughTurn: summary.throughTurn,
    foldCount: summary.foldCount,
    keeper: summary.keeper,
    foldMeter: summary.foldMeter === null ? null : { tokens: summary.foldMeter.tokens, estimated: summary.foldMeter.estimated },
  };
}

/** A stored summary read back, or null when the payload is not a valid summary. */
export function readCampaignSummary(data: JsonObject): CampaignSummary | null {
  if (validateCampaignSummary(data).length > 0) return null;
  const meter = data.foldMeter as JsonObject | null;
  return {
    text: data.text as string,
    throughTurn: data.throughTurn as number,
    foldCount: data.foldCount as number,
    keeper: data.keeper as string,
    foldMeter: meter === null ? null : { tokens: meter.tokens as number, estimated: meter.estimated as boolean },
  };
}

/**
 * The newest turn the summary covers; 0 for no summary. An unreadable summary also reads
 * as 0 — "nothing folded" — so a caller replays everything rather than dropping history
 * nothing covers.
 */
export function summaryThroughTurn(summary: CampaignSummary | null): number {
  return summary === null ? 0 : summary.throughTurn;
}

export type SummaryRefusalCode = "too_long";

/** The summary with the Keeper's margin replaced. */
export function setSummaryMargin(
  summary: CampaignSummary,
  margin: string,
): { readonly ok: true; readonly data: CampaignSummary } | { readonly ok: false; readonly code: SummaryRefusalCode; readonly path: string } {
  const text = margin.trim();
  if (codePoints(text) > MAX_KEEPER_MARGIN_CHARS) return { ok: false, code: "too_long", path: "keeper" };
  return { ok: true, data: { ...summary, keeper: text } };
}

/** The summary with its re-arm stamp set (or cleared with null). */
export function stampFoldMeter(summary: CampaignSummary, stamp: FoldMeterStamp | null): CampaignSummary {
  const same = stamp === null ? summary.foldMeter === null : summary.foldMeter !== null && summary.foldMeter.tokens === stamp.tokens && summary.foldMeter.estimated === stamp.estimated;
  return same ? summary : { ...summary, foldMeter: stamp === null ? null : { tokens: stamp.tokens, estimated: stamp.estimated } };
}

export type CampaignSummaryKeeperView = CampaignSummary;

export interface CampaignSummaryPublicView {
  readonly text: string;
  readonly throughTurn: number;
}

export type CampaignSummaryView = CampaignSummaryKeeperView | CampaignSummaryPublicView;

export function projectCampaignSummary(summary: CampaignSummary, viewer: Viewer): CampaignSummaryView {
  if (viewer.grade === "keeper") return { ...summary };
  return { text: summary.text, throughTurn: summary.throughTurn };
}

export const campaignSummaryDocumentType: DocumentType<CampaignSummaryView> = {
  name: CAMPAIGN_SUMMARY_TYPE,
  // A summary of play: a story reset clears it with the records it summarises.
  lifecycle: { reset: "story" },
  version: 1,
  project(document: Document, viewer: Viewer) {
    const summary = readCampaignSummary(document.data);
    return summary === null ? null : projectCampaignSummary(summary, viewer);
  },
  validate: validateCampaignSummary,
};
